{"command":"create","path":"/workspace/server/util.go","file_text":"package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"math"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type M = map[string]any

type apiErr struct {
	status int
	code   string
	msg    string
}

func errOf(status int, code, msg string) *apiErr {
	return &apiErr{status, code, msg}
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, M{"error": msg, "code": code})
}

func writeAPIErr(w http.ResponseWriter, e *apiErr) {
	writeErr(w, e.status, e.code, e.msg)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, v any) {
	writeJSON(w, status, M{"data": v})
}

func decodeBody(r *http.Request, dst any) *apiErr {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return errOf(400, "invalid_json", "request body is not valid JSON or contains unknown fields: "+err.Error())
	}
	return nil
}

func decodeRaw(r *http.Request) (map[string]json.RawMessage, []byte, *apiErr) {
	var raw map[string]json.RawMessage
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&raw); err != nil {
		return nil, nil, errOf(400, "invalid_json", "request body is not valid JSON: "+err.Error())
	}
	b, _ := json.Marshal(raw)
	return raw, b, nil
}

func newUUID() string { return uuid.NewString() }

func hashStr(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

func parseTime(s string) (time.Time, bool) {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

func fmtTime(t time.Time) string { return t.UTC().Format(time.RFC3339) }

func fmtTimePtr(t *time.Time) any {
	if t == nil {
		return nil
	}
	return fmtTime(*t)
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return 2 * R * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

var validRoles = map[string]bool{
	"administrator": true, "dispatcher": true, "requester": true,
	"collection_professional": true, "delivery_partner": true,
	"node_handler": true, "laboratory_team": true,
}

var validFunctions = map[string]bool{
	"collection_point": true, "transfer_point": true, "hub": true, "laboratory": true,
}

const staleLocationAfter = 5 * time.Minute

func isStale(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return time.Since(*recordedAt) > staleLocationAfter
}

func audit(actorID, role, action, entityType, entityID string, success bool, details M) {
	if details == nil {
		details = M{}
	}
	d, _ := json.Marshal(details)
	db.Exec(`INSERT INTO audit_log(audit_id,actor_id,role,action,entity_type,entity_id,success,details) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
		newUUID(), actorID, role, action, entityType, entityID, success, d)
}

func emitEvent(typ, entityType, entityID, audienceRole string, payload M) {
	p, _ := json.Marshal(payload)
	db.Exec(`INSERT INTO events(type,entity_type,entity_id,audience_role,payload) VALUES($1,$2,$3,$4,$5)`,
		typ, entityType, entityID, audienceRole, p)
	notifyEventListeners()
}

func nullUUID(s *string) any {
	if s == nil || *s == "" {
		return nil
	}
	return *s
}

func strOrEmpty(ns sql.NullString) string {
	if ns.Valid {
		return ns.String
	}
	return ""
}

// requireIdempotency validates and reserves nothing; returns stored response if replay.
// Returns (storedStatus, storedBody, done, err). If done, caller should write stored response.
func idempotencyLookup(userID, endpoint, key string, bodyHash string) (int, string, bool, *apiErr) {
	if key == "" {
		return 0, "", false, errOf(400, "idempotency_required", "idempotencyKey is required")
	}
	var status int
	var body, prevHash string
	err := db.QueryRow(`SELECT response_status, response_body, request_hash FROM idempotency_keys WHERE key=$1 AND user_id=$2 AND endpoint=$3`,
		key, userID, endpoint).Scan(&status, &body, &prevHash)
	if err == nil {
		if prevHash != bodyHash {
			return 0, "", false, errOf(409, "idempotency_conflict", "idempotency key was used with a different request")
		}
		return status, body, true, nil
	}
	return 0, "", false, nil
}

func idempotencyStore(userID, endpoint, key, bodyHash string, status int, body string) {
	db.Exec(`INSERT INTO idempotency_keys(key,user_id,endpoint,request_hash,response_status,response_body) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
		key, userID, endpoint, bodyHash, status, body)
}

// idemHandler wraps a handler with idempotency semantics when the request has idempotencyKey.
func respondIdempotent(w http.ResponseWriter, userID, endpoint, key string, rawBody []byte, fn func() (int, any, *apiErr)) {
	bodyHash := hashStr(string(rawBody))
	if key != "" {
		st, body, done, aerr := idempotencyLookup(userID, endpoint, key, bodyHash)
		if aerr != nil {
			writeAPIErr(w, aerr)
			return
		}
		if done {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(st)
			w.Write([]byte(body))
			return
		}
	}
	status, payload, aerr := fn()
	if aerr != nil {
		writeAPIErr(w, aerr)
		return
	}
	out, _ := json.Marshal(payload)
	if key != "" && status < 500 {
		idempotencyStore(userID, endpoint, key, bodyHash, status, string(out))
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(out)
}
"}

{"command":"create","path":"/workspace/server/auth.go","file_text":"package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type sessionInfo struct {
	token      string
	userID     string
	username   string
	activeRole string
	roles      []string
}

func getSession(r *http.Request) *sessionInfo {
	h := r.Header.Get("Authorization")
	if !strings.HasPrefix(h, "Bearer ") {
		return nil
	}
	return lookupSession(strings.TrimPrefix(h, "Bearer "))
}

func lookupSession(token string) *sessionInfo {
	if token == "" {
		return nil
	}
	var s sessionInfo
	var role sql.NullString
	err := db.QueryRow(`SELECT s.token, s.user_id, u.username, s.active_role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=$1 AND s.expires_at > now() AND u.active`, token).
		Scan(&s.token, &s.userID, &s.username, &role)
	if err != nil {
		return nil
	}
	s.activeRole = role.String
	s.roles = userRoles(s.userID)
	return &s
}

func userRoles(userID string) []string {
	rows, err := db.Query(`SELECT role FROM user_roles WHERE user_id=$1 ORDER BY role`, userID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var r string
		rows.Scan(&r)
		out = append(out, r)
	}
	return out
}

func userQualifications(userID string) []string {
	rows, err := db.Query(`SELECT code FROM user_qualifications WHERE user_id=$1 ORDER BY code`, userID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var c string
		rows.Scan(&c)
		out = append(out, c)
	}
	return out
}

func userCertifications(userID string) []M {
	rows, err := db.Query(`SELECT code, active, expires_at FROM user_certifications WHERE user_id=$1 ORDER BY code`, userID)
	if err != nil {
		return []M{}
	}
	defer rows.Close()
	out := []M{}
	for rows.Next() {
		var code string
		var active bool
		var exp *time.Time
		rows.Scan(&code, &active, &exp)
		m := M{"code": code, "active": active}
		if exp != nil {
			m["expiresAt"] = fmtTime(*exp)
		}
		out = append(out, m)
	}
	return out
}

func newToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}

// rolePerm maps operation -> allowed roles. administrator inherits dispatcher permissions.
var opRoles = map[string][]string{
	"check_serviceability":          {"requester", "dispatcher", "administrator"},
	"create_collection_request":     {"requester"},
	"ingest_presealed_sample":       {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"accept_assignment":             {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"decline_assignment":            {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"collect_and_seal_sample":       {"collection_professional"},
	"record_worker_location":        {"collection_professional", "delivery_partner"},
	"update_assignment_progress":    {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"initiate_handoff":              {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"confirm_handoff":               {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"record_handling_checkpoint":    {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"confirm_laboratory_receipt":    {"laboratory_team"},
	"record_laboratory_exception":   {"laboratory_team"},
	"configure_capacity":            {"node_handler", "laboratory_team", "administrator"},
	"configure_laboratory_acceptance": {"laboratory_team", "administrator"},
	"read_operations_state":         {"dispatcher", "administrator"},
	"cancel_journey":                {"dispatcher", "administrator"},
	"reroute_journey":               {"dispatcher", "administrator"},
	"split_journey":                 {"dispatcher", "administrator"},
	"merge_journeys":                {"dispatcher", "administrator"},
	"edit_active_plan":              {"dispatcher", "administrator"},
	"report_disruption":             {"dispatcher", "administrator"},
	"search_audit_trail":            {"dispatcher", "administrator"},
	"create_user":                   {"administrator"},
	"update_user_access":            {"administrator"},
	"create_location":               {"administrator"},
	"update_location":               {"administrator"},
	"create_connection":             {"administrator"},
	"create_sample_type":            {"administrator"},
	"update_sample_type":            {"administrator"},
	"set_location_status":           {"administrator"},
	"set_location_function_status":  {"administrator"},
	"set_connection_status":         {"administrator"},
	"set_worker_availability":       {"dispatcher", "administrator"},
	"list_role_work":                {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_journey_plan":             {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_serviceability_snapshot":  {"requester", "dispatcher", "administrator"},
}

func roleAllowed(op, role string) bool {
	allowed, ok := opRoles[op]
	if !ok {
		return true
	}
	for _, r := range allowed {
		if r == role {
			return true
		}
	}
	return false
}

// authMiddleware: validates session, role selection, and permission for the op.
func requireAuth(op string, needRole bool, w http.ResponseWriter, r *http.Request) *sessionInfo {
	s := getSession(r)
	if s == nil {
		writeErr(w, 401, "unauthorized", "authentication required")
		return nil
	}
	if needRole && s.activeRole == "" {
		audit(s.userID, "", op, "operation", op, false, M{"reason": "role_not_selected"})
		writeErr(w, 409, "role_not_selected", "an active role must be selected before performing this operation")
		return nil
	}
	if s.activeRole != "" && !roleAllowed(op, s.activeRole) {
		audit(s.userID, s.activeRole, op, "operation", op, false, M{"reason": "forbidden"})
		writeErr(w, 403, "forbidden", "role "+s.activeRole+" may not perform this operation")
		return nil
	}
	return s
}

func handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	var userID, hash string
	var active bool
	err := db.QueryRow(`SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &hash, &active)
	if err != nil || !active || bcrypt.CompareHashAndPassword([]byte(hash), []byte(req.Password)) != nil {
		audit("", "", "authenticate_user", "user", req.Username, false, M{"reason": "invalid_credentials"})
		writeErr(w, 401, "invalid_credentials", "invalid username or password")
		return
	}
	token := newToken()
	db.Exec(`INSERT INTO sessions(token,user_id,expires_at) VALUES($1,$2,$3)`, token, userID, time.Now().Add(24*time.Hour))
	roles := userRoles(userID)
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
		db.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, activeRole, token)
	}
	audit(userID, activeRole, "authenticate_user", "user", userID, true, M{"username": req.Username})
	writeData(w, 200, M{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

func handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("select_active_role", false, w, r)
	if s == nil {
		return
	}
	var raw struct {
		Role json.RawMessage `json:"role"`
	}
	if e := decodeBody(r, &raw); e != nil {
		writeAPIErr(w, e)
		return
	}
	var role string
	if err := json.Unmarshal(raw.Role, &role); err != nil || !validRoles[role] {
		writeErr(w, 400, "invalid_role", "role must be one of the known role names")
		return
	}
	held := false
	for _, ur := range s.roles {
		if ur == role {
			held = true
		}
	}
	if !held {
		audit(s.userID, s.activeRole, "select_active_role", "user", s.userID, false, M{"role": role})
		writeErr(w, 403, "role_not_held", "the selected role is not assigned to this user")
		return
	}
	db.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, role, s.token)
	audit(s.userID, role, "select_active_role", "user", s.userID, true, M{"role": role})
