func ensureInitialAdmin() {
	var n int
	db.QueryRow(`SELECT count(*) FROM users`).Scan(&n)
	if n > 0 {
		return
	}
	user := getenv("ADMIN_USERNAME", "admin")
	pass := getenv("ADMIN_PASSWORD", "admin")
	hash, _ := bcrypt.GenerateFromPassword([]byte(pass), bcrypt.DefaultCost)
	id := newUUID()
	_, err := db.Exec(`INSERT INTO users(id,username,password_hash,full_name,active) VALUES($1,$2,$3,$4,TRUE)`, id, user, string(hash), "Administrator")
	if err != nil {
		return
	}
	db.Exec(`INSERT INTO user_roles(user_id,role) VALUES($1,'administrator')`, id)
	audit(id, "administrator", "bootstrap_admin", "user", id, true, M{"username": user})
}

func getenv(k, def string) string {
	// avoid os import cycle concerns; simple wrapper
	if v := lookupEnv(k); v != "" {
		return v
	}
	return def
}
