// reservePathCapacity reserves capacity along a route; must be checked first.
func reservePathCapacity(p *pathResult, needCooled bool) {
	for _, c := range p.Conns {
		if needCooled {
			db.Exec(`UPDATE connections SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, c.ID)
		} else {
			db.Exec(`UPDATE connections SET reserved_units=reserved_units+1 WHERE id=$1`, c.ID)
		}
	}
	for _, nid := range p.Nodes[1:] {
		if needCooled {
			db.Exec(`UPDATE locations SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, nid)
		} else {
			db.Exec(`UPDATE locations SET reserved_units=reserved_units+1 WHERE id=$1`, nid)
		}
	}
}

func releasePathCapacity(p *pathResult, needCooled bool) {
	for _, c := range p.Conns {
		if needCooled {
			db.Exec(`UPDATE connections SET cooled_reserved_units=GREATEST(0,cooled_reserved_units-1) WHERE id=$1`, c.ID)
		} else {
			db.Exec(`UPDATE connections SET reserved_units=GREATEST(0,reserved_units-1) WHERE id=$1`, c.ID)
		}
	}
	for _, nid := range p.Nodes[1:] {
		if needCooled {
			db.Exec(`UPDATE locations SET cooled_reserved_units=GREATEST(0,cooled_reserved_units-1) WHERE id=$1`, nid)
		} else {
			db.Exec(`UPDATE locations SET reserved_units=GREATEST(0,reserved_units-1) WHERE id=$1`, nid)
		}
	}
}

// createJourneyForSample builds a journey with assignments for a single sample.
// Returns journeyID, error reason.
func createJourneyForSample(sampleID string, holderID *string, originType string) (string, *apiErr) {
	var reqID string
	var originLat, originLng float64
	var originNodeID *string
	var requestedAt, deadline time.Time
	var earliest, latest *time.Time
	var stID string
	var alreadySealed bool
	err := db.QueryRow(`SELECT r.id, r.origin_lat, r.origin_lng, r.origin_node_id, r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at, r.sample_type_id, r.already_sealed, r.origin_type
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&reqID, &originLat, &originLng, &originNodeID, &requestedAt, &deadline, &earliest, &latest, &stID, &alreadySealed, &originType)
	if err != nil {
		return "", errOf(404, "not_found", "sample not found")
	}
	st := loadSampleType(stID)
	onID := ""
	if originNodeID != nil {
		onID = *originNodeID
	}
	ok, reason, labID, eta := serviceabilityCheck(originLat, originLng, originType, onID, st, requestedAt, deadline, earliest)
	if !ok {
		return "", errOf(422, reason, "request is not serviceable: "+reason)
	}
	locs := loadLocations()
	conns := loadConnections()
	// pick entry node again (same logic as serviceabilityCheck)
	var entry *locInfo
	if originType == "node" && onID != "" {
		entry = locs[onID]
	} else {
		for _, l := range locs {
			if l.Active && l.CP && haversineKm(originLat, originLng, l.Lat, l.Lng) <= l.CovKm {
				if entry == nil || haversineKm(originLat, originLng, l.Lat, l.Lng) < haversineKm(originLat, originLng, entry.Lat, entry.Lng) {
					entry = l
				}
			}
		}
	}
	accepting := map[string]bool{labID: true}
	p := findRoute(locs, conns, entry.ID, accepting, st.RequiresCooled, true)
	if p == nil || !p.HasCapacity {
		return "", errOf(422, "insufficient_capacity", "no capacity available on route")
	}
	reservePathCapacity(p, st.RequiresCooled)

	journeyID := newUUID()
	routeMode := "direct"
	if len(p.Nodes) > 2 {
		routeMode = "multi_stop"
	}
	stops := []M{}
	seq := 0
	originCoord := M{"latitude": originLat, "longitude": originLng}
	stops = append(stops, M{
		"stopId": newUUID(), "locationId": entry.ID, "stopType": "pickup", "sequence": seq,
		"estimatedAt": fmtTime(requestedAt), "coordinate": originCoord,
	})
	seq++
	for _, nid := range p.Nodes[1 : len(p.Nodes)-1] {
		l := locs[nid]
		stops = append(stops, M{
			"stopId": newUUID(), "locationId": nid, "stopType": "handoff", "sequence": seq,
			"estimatedAt": fmtTime(eta), "coordinate": M{"latitude": l.Lat, "longitude": l.Lng},
		})
		seq++
	}
	lab := locs[labID]
	stops = append(stops, M{
		"stopId": newUUID(), "locationId": labID, "stopType": "delivery", "sequence": seq,
		"estimatedAt": fmtTime(eta), "coordinate": M{"latitude": lab.Lat, "longitude": lab.Lng},
	})
	stopsJSON, _ := json.Marshal(stops)
	db.Exec(`INSERT INTO journeys(id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,target_laboratory_id,stops) VALUES($1,1,$2,'planned',$3,$4,$5,$6)`,
		journeyID, routeMode, eta, p.Cost, labID, stopsJSON)
	db.Exec(`INSERT INTO journey_samples(journey_id,sample_id) VALUES($1,$2)`, journeyID, sampleID)
	db.Exec(`UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2 WHERE id=$3`, journeyID, labID, sampleID)

	// assignments
	aseq := 0
	if !alreadySealed {
		db.Exec(`INSERT INTO assignments(id,journey_id,sample_id,kind,sequence,from_location_id,to_location_id,status) VALUES($1,$2,$3,'collection',$4,NULL,$5,'pending')`,
			newUUID(), journeyID, sampleID, aseq, entry.ID)
		aseq++
	}
	prevLoc := entry.ID
	// first transport leg from origin to entry node (only if origin is not the node itself)
	if originType != "node" {
		db.Exec(`INSERT INTO assignments(id,journey_id,sample_id,kind,sequence,from_location_id,to_location_id,status) VALUES($1,$2,$3,'transport',$4,NULL,$5,'pending')`,
			newUUID(), journeyID, sampleID, aseq, entry.ID)
		aseq++
	}
	for i, c := range p.Conns {
		db.Exec(`INSERT INTO assignments(id,journey_id,sample_id,kind,sequence,from_location_id,to_location_id,status) VALUES($1,$2,$3,'transport',$4,$5,$6,'pending')`,
			newUUID(), journeyID, sampleID, aseq, c.From, c.To)
		aseq++
		if i < len(p.Conns)-1 {
			db.Exec(`INSERT INTO assignments(id,journey_id,sample_id,kind,sequence,node_id,status) VALUES($1,$2,$3,'node',$4,$5,'pending')`,
				newUUID(), journeyID, sampleID, aseq, c.To)
			aseq++
		}
		prevLoc = c.To
	}
	_ = prevLoc
	db.Exec(`INSERT INTO assignments(id,journey_id,sample_id,kind,sequence,laboratory_id,status) VALUES($1,$2,$3,'laboratory',$4,$5,'pending')`,
		newUUID(), journeyID, sampleID, aseq, labID)
	maybeOfferNext(journeyID)
	return journeyID, nil
}

// timelineForSample builds ordered timeline entries from audit log.
func timelineForSample(sampleID string) []M {
	rows, err := db.Query(`SELECT audit_id, action, actor_id, role, occurred_at, details FROM audit_log
		WHERE (entity_type='sample' AND entity_id=$1)
		   OR (entity_type='request' AND entity_id=(SELECT request_id FROM samples WHERE id=$1))
		   OR (entity_type='assignment' AND entity_id IN (SELECT id FROM assignments WHERE sample_id=$1))
		   OR (entity_type='handoff' AND entity_id IN (SELECT id FROM handoffs WHERE sample_id=$1))
		ORDER BY occurred_at, seq`, sampleID)
	if err != nil {
		return []M{}
	}
	defer rows.Close()
	out := []M{}
	for rows.Next() {
		var aid, action, actorID, role string
		var at time.Time
		var details []byte
		rows.Scan(&aid, &action, &actorID, &role, &at, &details)
		var det M
		json.Unmarshal(details, &det)
		if det == nil {
			det = M{}
		}
		out = append(out, M{
			"entryId": aid, "action": action, "actorId": actorID, "role": role,
			"occurredAt": fmtTime(at), "details": det,
		})
	}
	return out
}

func sampleLocationFields(status string, lat, lng *float64, recordedAt *time.Time) M {
	m := M{"locationStale": isStale(recordedAt)}
	if lat != nil && lng != nil {
		m["latestLocation"] = M{"latitude": *lat, "longitude": *lng}
	}
	if recordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*recordedAt)
	}
	return m
}

func readSampleState(sampleID string) M {
	var reqID, requesterID, originType, stID, container string
	var originLat, originLng, tmin, tmax float64
	var requestedAt, deadline time.Time
	var incompat []string
	var serviceability string
	var status string
	var holder, journeyID, labID *string
	var lat, lng *float64
	var recAt *time.Time
	err := db.QueryRow(`SELECT s.request_id, r.requester_id, r.origin_lat, r.origin_lng, r.origin_type, r.requested_at, r.delivery_deadline,
		r.sample_type_id, r.container_type, r.temp_min, r.temp_max, r.incompatible_sample_types, r.serviceability,
		s.status, s.current_holder_id, s.active_journey_id, s.target_laboratory_id, s.last_lat, s.last_lng, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&reqID, &requesterID, &originLat, &originLng, &originType, &requestedAt, &deadline,
			&stID, &container, &tmin, &tmax, pq.Array(&incompat), &serviceability,
			&status, &holder, &journeyID, &labID, &lat, &lng, &recAt)
	if err != nil {
		return nil
	}
	if incompat == nil {
		incompat = []string{}
	}
	var activeAsgs []string
	db.QueryRow(`SELECT COALESCE(array_agg(id),'{}') FROM assignments WHERE sample_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, sampleID).Scan(pq.Array(&activeAsgs))
	m := M{
		"sampleId": sampleID, "requestId": reqID, "requesterId": requesterID,
		"origin": M{"latitude": originLat, "longitude": originLng},
		"originType": originType, "requestedAt": fmtTime(requestedAt), "deliveryDeadline": fmtTime(deadline),
		"sampleTypeId": stID, "containerType": container,
		"temperatureMinC": tmin, "temperatureMaxC": tmax,
		"incompatibleSampleTypes": incompat,
		"serviceability": serviceability,
		"activeAssignmentIds": activeAsgs,
		"state":    M{"status": status},
		"timeline": timelineForSample(sampleID),
	}
	if journeyID != nil {
		m["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		m["targetLaboratoryId"] = *labID
	}
	for k, v := range sampleLocationFields(status, lat, lng, recAt) {
		m[k] = v
	}
	return m
}

func readSampleLifecycle(sampleID string) M {
	var status string
	var sealed bool
	var holder, journeyID, labID *string
	var exception []byte
	var lat, lng *float64
	var recAt *time.Time
	err := db.QueryRow(`SELECT status,sealed,current_holder_id,active_journey_id,received_laboratory_id,exception,last_lat,last_lng,location_recorded_at FROM samples WHERE id=$1`, sampleID).
		Scan(&status, &sealed, &holder, &journeyID, &labID, &exception, &lat, &lng, &recAt)
	if err != nil {
		return nil
	}
	var completedLegs []string
	db.QueryRow(`SELECT COALESCE(array_agg(id),'{}') FROM assignments WHERE sample_id=$1 AND status='completed'`, sampleID).Scan(pq.Array(&completedLegs))
	var pendingHandoff *string
	db.QueryRow(`SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY created_at DESC LIMIT 1`, sampleID).Scan(&pendingHandoff)
	m := M{
		"sampleId": sampleID, "status": status, "sealed": sealed,
		"completedLegIds": completedLegs, "activeReplacementPlanIds": []string{},
		"timeline": timelineForSample(sampleID),
	}
	if journeyID != nil {
		m["activeJourneyId"] = *journeyID
	}
	if holder != nil {
		m["currentHolderId"] = *holder
	}
	if labID != nil {
		m["receivedLaboratoryId"] = *labID
	}
	if len(exception) > 0 {
		var ex M
		json.Unmarshal(exception, &ex)
		m["exception"] = ex
	}
	if pendingHandoff != nil {
		m["pendingHandoffId"] = *pendingHandoff
		m["pendingHandoff"] = handoffJSON(*pendingHandoff)
	}
	for k, v := range sampleLocationFields(status, lat, lng, recAt) {
		m[k] = v
	}
	return m
}

func handoffJSON(id string) M {
	var sampleID, fromA, toA, sender, receiver, status string
	var sc, rc bool
	var createdAt time.Time
	var confirmedAt *time.Time
	err := db.QueryRow(`SELECT sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,status,sender_confirmed,receiver_confirmed,created_at,confirmed_at FROM handoffs WHERE id=$1`, id).
		Scan(&sampleID, &fromA, &toA, &sender, &receiver, &status, &sc, &rc, &createdAt, &confirmedAt)
	if err != nil {
		return nil
	}
	m := M{
		"handoffId": id, "sampleId": sampleID, "fromAssignmentId": fromA, "toAssignmentId": toA,
		"senderId": sender, "receiverId": receiver, "status": status,
		"senderConfirmed": sc, "receiverConfirmed": rc, "initiatedAt": fmtTime(createdAt),
	}
	if confirmedAt != nil {
		m["confirmedAt"] = fmtTime(*confirmedAt)
	}
	return m
}

