{"command":"create","path":"/workspace/server/events.go","file_text":"package main

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var (
	eventMu       sync.Mutex
	eventListeners = map[chan struct{}]bool{}
)

func notifyEventListeners() {
	eventMu.Lock()
	defer eventMu.Unlock()
	for ch := range eventListeners {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func eventsSince(since int64, limit int) ([]M, int64) {
	if limit <= 0 || limit > 500 {
		limit = 200
	}
	rows, err := db.Query(`SELECT seq,type,entity_type,entity_id,payload,created_at FROM events WHERE seq > $1 ORDER BY seq LIMIT $2`, since, limit)
	if err != nil {
		return []M{}, since
	}
	defer rows.Close()
	out := []M{}
	cursor := since
	for rows.Next() {
		var seq int64
		var typ, et, eid string
		var payload []byte
		var createdAt time.Time
		rows.Scan(&seq, &typ, &et, &eid, &payload, &createdAt)
		var p M
		json.Unmarshal(payload, &p)
		if p == nil {
			p = M{}
		}
		out = append(out, M{
			"id": seq, "type": typ, "entityType": et, "entityId": eid,
			"payload": p, "createdAt": fmtTime(createdAt),
		})
		cursor = seq
	}
	return out, cursor
}

func handleEvents(w http.ResponseWriter, r *http.Request) {
	// authenticate via Authorization header or websocket subprotocol bearer.<token>
	token := ""
	if h := r.Header.Get("Authorization"); strings.HasPrefix(h, "Bearer ") {
		token = strings.TrimPrefix(h, "Bearer ")
	}
	subproto := r.Header.Get("Sec-WebSocket-Protocol")
	if token == "" && strings.HasPrefix(subproto, "bearer.") {
		dec, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(subproto, "bearer."))
		if err == nil {
			token = string(dec)
		} else {
			token = strings.TrimPrefix(subproto, "bearer.")
		}
	}
	sess := lookupSession(token)
	if sess == nil {
		writeErr(w, 401, "unauthorized", "authentication required")
		return
	}
	var since int64
	if v := r.URL.Query().Get("since"); v != "" {
		json.Unmarshal([]byte(v), &since)
	}
	isWS := strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") &&
		strings.EqualFold(r.Header.Get("Upgrade"), "websocket")
	if !isWS {
		events, cursor := eventsSince(since, 200)
		writeData(w, 200, M{"events": events, "cursor": cursor})
		return
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	ch := make(chan struct{}, 1)
	eventMu.Lock()
	eventListeners[ch] = true
	eventMu.Unlock()
	defer func() {
		eventMu.Lock()
		delete(eventListeners, ch)
		eventMu.Unlock()
	}()
	// initial burst
	send := func() bool {
		events, cursor := eventsSince(since, 200)
		since = cursor
		for _, ev := range events {
			if err := conn.WriteJSON(ev); err != nil {
				return false
			}
		}
		return true
	}
	if !send() {
		return
	}
	conn.SetReadDeadline(time.Now().Add(60 * time.Second))
	go func() {
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				conn.Close()
				return
			}
		}
	}()
	for {
		select {
		case <-ch:
			if !send() {
				return
			}
		case <-time.After(30 * time.Second):
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}
"}

{"command":"create","path":"/workspace/server/main.go","file_text":"package main

import (
	"encoding/json"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

func readyHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		writeJSON(w, 503, M{"status": "unavailable"})
		return
	}
	writeJSON(w, 200, M{"status": "ready"})
}

func methodNotAllowed(w http.ResponseWriter, r *http.Request) {
	writeErr(w, 405, "method_not_allowed", "method not allowed")
}

func post(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			methodNotAllowed(w, r)
			return
		}
		h(w, r)
	}
}

func get(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			methodNotAllowed(w, r)
			return
		}
		h(w, r)
	}
}

func main() {
	connectDB()
	migrate()
	seedSampleTypes()
	ensureInitialAdmin()
	if _, ok := kvGet("snapshot_initialized"); !ok {
		recomputeServiceabilitySnapshot()
		kvSet("snapshot_initialized", "1")
	}

	// background offer sweeper
	go func() {
		for {
			sweepExpiredOffers()
			time.Sleep(2 * time.Second)
		}
	}()

	mux := http.NewServeMux()
	mux.HandleFunc("/ready", readyHandler)
	mux.HandleFunc("/api/ready", readyHandler)

	mux.HandleFunc("/api/authenticate-user", post(handleAuthenticate))
	mux.HandleFunc("/api/select-active-role", post(handleSelectActiveRole))
	mux.HandleFunc("/api/read-user/{userId}", get(handleReadUser))
	mux.HandleFunc("/api/check-serviceability", post(handleCheckServiceability))
	mux.HandleFunc("/api/create-collection-request", post(handleCreateCollectionRequest))
	mux.HandleFunc("/api/ingest-presealed-sample", post(handleIngestPresealed))
	mux.HandleFunc("/api/accept-assignment", post(handleAcceptAssignment))
	mux.HandleFunc("/api/decline-assignment", post(handleDeclineAssignment))
	mux.HandleFunc("/api/collect-and-seal-sample", post(handleCollectAndSeal))
	mux.HandleFunc("/api/record-worker-location", post(handleRecordWorkerLocation))
	mux.HandleFunc("/api/update-assignment-progress", post(handleUpdateProgress))
	mux.HandleFunc("/api/initiate-handoff", post(handleInitiateHandoff))
	mux.HandleFunc("/api/confirm-handoff", post(handleConfirmHandoff))
	mux.HandleFunc("/api/record-handling-checkpoint", post(handleRecordCheckpoint))
	mux.HandleFunc("/api/confirm-laboratory-receipt", post(handleConfirmLabReceipt))
	mux.HandleFunc("/api/record-laboratory-exception", post(handleRecordLabException))
	mux.HandleFunc("/api/read-sample-state/{sampleId}", get(handleReadSampleState))
	mux.HandleFunc("/api/read-sample-lifecycle/{sampleId}", get(handleReadSampleLifecycle))
	mux.HandleFunc("/api/list-role-work", post(handleListRoleWork))
	mux.HandleFunc("/api/read-journey-plan", post(handleReadJourneyPlan))
	mux.HandleFunc("/api/read-operations-state", get(handleReadOperationsState))
	mux.HandleFunc("/api/cancel-journey", post(handleCancelJourney))
	mux.HandleFunc("/api/reroute-journey", post(handleRerouteJourney))
	mux.HandleFunc("/api/split-journey", post(handleSplitJourney))
	mux.HandleFunc("/api/merge-journeys", post(handleMergeJourneys))
	mux.HandleFunc("/api/edit-active-plan", post(handleEditActivePlan))
	mux.HandleFunc("/api/report-disruption", post(handleReportDisruption))
	mux.HandleFunc("/api/search-audit-trail", post(handleSearchAudit))
	mux.HandleFunc("/api/create-user", post(handleCreateUser))
	mux.HandleFunc("/api/update-user-access", post(handleUpdateUserAccess))
	mux.HandleFunc("/api/create-location", post(handleCreateLocation))
	mux.HandleFunc("/api/update-location", post(handleUpdateLocation))
	mux.HandleFunc("/api/create-connection", post(handleCreateConnection))
	mux.HandleFunc("/api/create-sample-type", post(handleCreateSampleType))
	mux.HandleFunc("/api/update-sample-type", post(handleUpdateSampleType))
	mux.HandleFunc("/api/set-location-status", post(handleSetLocationStatus))
	mux.HandleFunc("/api/set-location-function-status", post(handleSetLocationFunctionStatus))
	mux.HandleFunc("/api/set-connection-status", post(handleSetConnectionStatus))
	mux.HandleFunc("/api/configure-capacity", post(handleConfigureCapacity))
	mux.HandleFunc("/api/configure-laboratory-acceptance", post(handleConfigureLabAcceptance))
	mux.HandleFunc("/api/set-worker-availability", post(handleSetWorkerAvailability))
	mux.HandleFunc("/api/read-serviceability-snapshot", get(handleReadServiceabilitySnapshot))
	mux.HandleFunc("/api/events", handleEvents)
	mux.HandleFunc("/api/ui/bootstrap", get(handleUIBootstrap))
	mux.HandleFunc("/api/openapi.json", get(func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, openapiPath())
	}))

	// static assets: map-assets and frontend
	webDir := os.Getenv("WEB_DIR")
	if webDir == "" {
		webDir = "/workspace/web/dist"
	}
	mapDir := os.Getenv("MAP_ASSETS_DIR")
	if mapDir == "" {
		mapDir = "/workspace/assets/map-assets"
	}
	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir))))
	mux.HandleFunc("/", spaHandler(webDir))

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	log.Printf("listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, mux))
}

func openapiPath() string {
	if p := os.Getenv("OPENAPI_PATH"); p != "" {
		return p
	}
	return "/workspace/app-setup/openapi.json"
}

func spaHandler(dir string) http.HandlerFunc {
	fs := http.FileServer(http.Dir(dir))
	return func(w http.ResponseWriter, r *http.Request) {
		p := filepath.Join(dir, filepath.Clean(r.URL.Path))
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, filepath.Join(dir, "index.html"))
	}
}

func handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("ui_bootstrap", false, w, r)
	if s == nil {
		return
	}
	sampleTypes := []M{}
	rows, _ := db.Query(`SELECT id FROM sample_types ORDER BY name`)
	if rows != nil {
		for rows.Next() {
			var id string
			rows.Scan(&id)
			sampleTypes = append(sampleTypes, sampleTypeJSON(id))
		}
		rows.Close()
	}
	writeData(w, 200, M{
		"user":        readUserByIDMust(s.userID),
		"activeRole":  s.activeRole,
		"roles":       s.roles,
		"sampleTypes": sampleTypes,
		"mapStyle":    "/map-assets/style.json",
	})
}

func readUserByIDMust(id string) M {
	m, _ := readUserByID(id)
	if m == nil {
		return M{"userId": id}
	}
	return m
}

var _ = json.Marshal
"}

