func handoffInitiateJSON(id string) M {
	var sender, receiver string
	var holder *string
	db.QueryRow(`SELECT h.sender_id, h.receiver_id, s.current_holder_id FROM handoffs h JOIN samples s ON s.id=h.sample_id WHERE h.id=$1`, id).
		Scan(&sender, &receiver, &holder)
	cur := ""
	if holder != nil {
		cur = *holder
	}
	return M{"handoffId": id, "senderId": sender, "receiverId": receiver, "currentHolderId": cur, "status": "pending"}
}

func handoffConfirmJSON(id string) M {
	var sender, receiver, status string
	var sc, rc bool
	var holder *string
	db.QueryRow(`SELECT h.sender_id, h.receiver_id, h.status, h.sender_confirmed, h.receiver_confirmed, s.current_holder_id FROM handoffs h JOIN samples s ON s.id=h.sample_id WHERE h.id=$1`, id).
		Scan(&sender, &receiver, &status, &sc, &rc, &holder)
	cur := ""
	if holder != nil {
		cur = *holder
	}
	return M{"handoffId": id, "status": status, "senderConfirmed": sc, "receiverConfirmed": rc, "currentHolderId": cur}
}"}

