{"command":"create","path":"/workspace/web/src/api.ts","file_text":"export class ApiError extends Error {
  code: string
  status: number
  constructor(status: number, code: string, message: string) {
    super(message)
    this.status = status
    this.code = code
  }
}

let token: string | null = localStorage.getItem('sessionToken')

export function getToken() {
  return token
}
export function setToken(t: string | null) {
  token = t
  if (t) localStorage.setItem('sessionToken', t)
  else localStorage.removeItem('sessionToken')
}

export async function api(path: string, body?: any, method?: string): Promise<any> {
  const headers: Record<string, string> = {}
  if (token) headers['Authorization'] = `Bearer ${token}`
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const res = await fetch(`/api/${path}`, {
    method: method || (body !== undefined ? 'POST' : 'GET'),
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  })
  let json: any = null
  try {
    json = await res.json()
  } catch {
    /* empty */
  }
  if (!res.ok) {
    throw new ApiError(res.status, json?.code || 'error', json?.error || `Request failed (${res.status})`)
  }
  return json?.data ?? json
}

export const errText = (e: any) => (e instanceof ApiError ? `${e.message} (${e.code})` : String(e?.message || e))
"}

