function PresealedForm({ onCreated }: { onCreated: () => void }) {
  const types = useSampleTypes()
  const [form, setForm] = useState({ lat: '12.9716', lon: '77.5946', sampleTypeId: '', deadline: '', requesterId: '', originNodeId: '' })
  const [err, setErr] = useState<string | null>(null)
  const [result, setResult] = useState<any>(null)
  const submit = async (e: any) => {
    e.preventDefault()
    setErr(null)
    try {
      const t = types.find((x) => x.sampleTypeId === form.sampleTypeId)
      const data = await api('ingest-presealed-sample', {
        requesterId: form.requesterId || undefined,
        origin: { latitude: parseFloat(form.lat), longitude: parseFloat(form.lon) },
        originType: form.originNodeId ? 'node' : 'clinic',
        originNodeId: form.originNodeId || undefined,
        requestedAt: now(),
        deliveryDeadline: toISO(form.deadline),
        sampleTypeId: form.sampleTypeId,
        containerType: t?.containerType || 'standard',
        temperatureMinC: t?.temperatureMinC ?? -80,
        temperatureMaxC: t?.temperatureMaxC ?? 30,
        idempotencyKey: uuid(),
      })
      setResult(data)
      onCreated()
    } catch (e2) {
      setErr(errText(e2))
    }
  }
  return (
    <div className="card">
      <h2>Register pre-sealed sample</h2>
      <p>Register a sample already collected and sealed that you currently hold. Origin must be a clinic or network node.</p>
      <ErrorBox err={err} />
      {result && <div className="info-box">Registered sample <span className="mono">{result.sampleId}</span></div>}
      <form onSubmit={submit}>
        <Field label="Current latitude">
          <input aria-label="Current latitude" type="number" step="any" value={form.lat} onChange={(e) => setForm({ ...form, lat: e.target.value })} />
        </Field>
        <Field label="Current longitude">
          <input aria-label="Current longitude" type="number" step="any" value={form.lon} onChange={(e) => setForm({ ...form, lon: e.target.value })} />
        </Field>
        <Field label="Origin node id (optional)">
          <input aria-label="Origin node id" value={form.originNodeId} onChange={(e) => setForm({ ...form, originNodeId: e.target.value })} />
        </Field>
        <Field label="Sample type">
          <SampleTypeSelect value={form.sampleTypeId} onChange={(v) => setForm({ ...form, sampleTypeId: v })} types={types} />
        </Field>
        <Field label="Delivery deadline">
          <input aria-label="Delivery deadline" type="datetime-local" value={form.deadline} onChange={(e) => setForm({ ...form, deadline: e.target.value })} />
        </Field>
        <button className="primary" type="submit">
          Register sample
        </button>
      </form>
    </div>
  )
}

