function Monitor() {
  const [ops, setOps] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const load = useCallback(() => {
    api('read-operations-state')
      .then(setOps)
      .catch((e) => setErr(errText(e)))
  }, [])
  useEffect(load, [load])
  const act = async (path: string, body: any) => {
    setErr(null)
    try {
      await api(path, body)
      load()
    } catch (e) {
      setErr(errText(e))
    }
  }
  if (!ops) return <p>Loading…</p>
  return (
    <>
      <ErrorBox err={err} />
      <div className="card">
        <h3>Samples ({ops.samples.length})</h3>
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Status</th>
              <th>Current holder</th>
              <th>Location</th>
              <th>Freshness</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {ops.samples.map((s: any) => (
              <tr key={s.sampleId}>
                <td className="mono">{s.sampleId}</td>
                <td>
                  <span className={`badge ${s.status}`}>{s.status}</span>
                </td>
                <td className="mono">{s.currentHolderId || '—'}</td>
                <td className="mono">{s.latestLocation ? `${s.latestLocation.latitude}, ${s.latestLocation.longitude}` : '—'}</td>
                <td>{s.locationStale ? <span className="badge stale">Stale</span> : <span className="badge ok">Fresh</span>}</td>
                <td>
                  <button className="small" onClick={() => setSelected(s.sampleId)}>
                    Details
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="grid2">
        <div className="card">
          <h3>Workers ({ops.workers.length})</h3>
          <table>
            <thead>
              <tr>
                <th>Worker</th>
                <th>Roles</th>
                <th>Status</th>
                <th>Assignments</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {ops.workers.map((w: any) => (
                <tr key={w.workerId}>
                  <td>
                    {w.fullName || ''} <span className="mono">{w.workerId}</span>
                  </td>
                  <td>{(w.roles || []).join(', ')}</td>
                  <td>
                    <span className={`badge ${w.status === 'available' ? 'ok' : 'exception'}`}>{w.status}</span>
                    {w.locationStale && <span className="badge stale">stale</span>}
                  </td>
                  <td>{w.assignmentCount}</td>
                  <td>
                    <button className="small" onClick={() => act('set-worker-availability', { workerId: w.workerId, available: !w.available, capacityUnits: w.capacityUnits })}>
                      {w.available ? 'Mark unavailable' : 'Mark available'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="card">
          <h3>Locations ({ops.locations.length})</h3>
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Functions</th>
                <th>Active</th>
                <th>Capacity (reg/cooled)</th>
              </tr>
            </thead>
            <tbody>
              {ops.locations.map((l: any) => (
                <tr key={l.locationId}>
                  <td>{l.name}</td>
                  <td className="mono">{JSON.stringify(l.functions)}</td>
                  <td>{l.active ? <span className="badge ok">active</span> : <span className="badge exception">inactive</span>}</td>
                  <td>
                    {l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} · ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}` : '—'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      <div className="grid2">
        <div className="card">
          <h3>Connections ({ops.connections.length})</h3>
          <table>
            <thead>
              <tr>
                <th>From</th>
                <th>To</th>
                <th>Active</th>
              </tr>
            </thead>
            <tbody>
              {ops.connections.map((c: any, i: number) => (
                <tr key={c.connectionId || i}>
                  <td className="mono">{c.fromLocationId}</td>
                  <td className="mono">{c.toLocationId}</td>
                  <td>{String(c.active)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="card">
          <h3>Exceptions ({ops.exceptions.length})</h3>
          {ops.exceptions.length === 0 && <p>No exceptions.</p>}
          <table>
            <tbody>
              {ops.exceptions.map((x: any, i: number) => (
                <tr key={i}>
                  <td className="mono">{JSON.stringify(x)}</td>
                </tr>
              ))}
            </tbody>
