function AuditView() {
  const [form, setForm] = useState({ query: '', entityType: '', entityId: '', action: '', role: '' })
  const [result, setResult] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  const search = async (e?: any) => {
    e?.preventDefault()
    setErr(null)
    try {
      const body: any = { limit: 100, offset: 0, order: 'newest_first' }
      if (form.query) body.query = form.query
      if (form.entityType) body.entityType = form.entityType
      if (form.entityId) body.entityId = form.entityId
      if (form.action) body.action = form.action
      if (form.role) body.role = form.role
      setResult(await api('search-audit-trail', body))
    } catch (e2) {
      setErr(errText(e2))
    }
  }
  useEffect(() => {
    search()
  }, [])
  return (
    <div className="card">
      <h2>Audit trail</h2>
      <ErrorBox err={err} />
      <form onSubmit={search}>
        <div className="grid2">
          <Field label="Search text">
            <input aria-label="Search text" value={form.query} onChange={(e) => setForm({ ...form, query: e.target.value })} />
          </Field>
          <Field label="Entity type">
            <input aria-label="Entity type" value={form.entityType} onChange={(e) => setForm({ ...form, entityType: e.target.value })} />
          </Field>
          <Field label="Entity id">
            <input aria-label="Entity id" value={form.entityId} onChange={(e) => setForm({ ...form, entityId: e.target.value })} />
          </Field>
          <Field label="Action">
            <input aria-label="Action" value={form.action} onChange={(e) => setForm({ ...form, action: e.target.value })} />
          </Field>
        </div>
        <button className="primary" type="submit">
          Search
        </button>
      </form>
      {result && (
        <>
          <p>
            {result.total} entries, showing {result.returned}
          </p>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((en: any) => (
                <tr key={en.auditId}>
                  <td>{en.occurredAt}</td>
                  <td className="mono">{en.actorId}</td>
                  <td>{en.role || en.actorRole}</td>
                  <td>{en.action}</td>
                  <td className="mono">
                    {en.entityType}/{en.entityId}
                  </td>
                  <td>{en.success ? <span className="badge ok">success</span> : <span className="badge exception">failed</span>}</td>
                  <td className="mono" style={{ maxWidth: 320, wordBreak: 'break-all' }}>
                    {JSON.stringify(en.details)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}
    </div>
  )
}

