function MapTab({ role }: { role: string }) {
  const [markers, setMarkers] = useState<MapMarker[]>([])
  const [note, setNote] = useState('')
  useEffect(() => {
    ;(async () => {
      const ms: MapMarker[] = []
      if (['dispatcher', 'administrator'].includes(role)) {
        try {
          const ops = await api('read-operations-state')
          for (const l of ops.locations || [])
            ms.push({ id: l.locationId, latitude: l.coordinate.latitude, longitude: l.coordinate.longitude, color: l.functions?.laboratory ? '#b3261e' : '#0d3b66', label: l.name })
          for (const w of ops.workers || [])
            if (w.latestLocation) ms.push({ id: w.workerId, latitude: w.latestLocation.latitude, longitude: w.latestLocation.longitude, color: '#2e7d32', label: w.fullName || w.workerId })
          for (const s of ops.samples || [])
            if (s.latestLocation) ms.push({ id: s.sampleId, latitude: s.latestLocation.latitude, longitude: s.latestLocation.longitude, color: '#fca311', label: `sample ${s.sampleId}` })
        } catch {
          setNote('Operations state unavailable for this role.')
        }
      } else {
        try {
          const snap = await api('read-serviceability-snapshot')
          for (const r of snap.regions || [])
            ms.push({ id: r.locationId, latitude: r.latitude, longitude: r.longitude, color: '#0d3b66', label: r.name })
          setNote(`Serviceability calculation version ${snap.version} (network revision ${snap.networkRevision})`)
        } catch {
          setNote('No serviceability snapshot available.')
        }
      }
      setMarkers(ms)
    })()
  }, [role])
  return (
    <div className="card">
      <h2>Live network map</h2>
      {note && <p>{note}</p>}
      <MapView markers={markers} />
    </div>
  )
}
"}

